"use client";

import { useEffect, useState } from "react";
import axios from "axios";
import { Activity, Database, RefreshCw, Server, CheckCircle2, AlertTriangle, XCircle, Heart } from "lucide-react";
import { Button } from "@/components/ui/button";
import BreadcrumbNav from "@/components/breadcrumb-nav";

interface HealthSummary {
  status: string;
  version: string;
  environment: string;
  services: {
    api: string;
    database: string;
    redis: string;
  };
  traceId: string;
}

export default function HealthUi() {
  const [data, setData] = useState<HealthSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [mounted, setMounted] = useState(false);

  const fetchHealth = async () => {
    try {
      setError(null);
      const apiUrl = process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:5024";
      const response = await axios.get<HealthSummary>(`${apiUrl}/api/system/health-summary`, {
        timeout: 5000
      });
      setData(response.data);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Failed to fetch health status from API";
      setError(message);
      setData(null);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    setMounted(true);
    const timeout = window.setTimeout(fetchHealth, 0);
    const interval = window.setInterval(fetchHealth, 10000);

    return () => {
      window.clearTimeout(timeout);
      window.clearInterval(interval);
    };
  }, []);

  const handleRefresh = () => {
    setRefreshing(true);
    fetchHealth();
  };

  const getStatusIcon = (status: string) => {
    switch (status?.toLowerCase()) {
      case "healthy":
      case "enabled":
        return <CheckCircle2 className="h-5 w-5 text-emerald-500 animate-pulse" />;
      case "pending":
      case "unhealthy":
        return <AlertTriangle className="h-5 w-5 text-yellow-500" />;
      case "disabled":
        return <XCircle className="h-5 w-5 text-zinc-500" />;
      default:
        return <XCircle className="h-5 w-5 text-red-500" />;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status?.toLowerCase()) {
      case "healthy":
      case "enabled":
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
            Healthy
          </span>
        );
      case "pending":
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-500/10 text-yellow-400 border border-yellow-500/20">
            Pending
          </span>
        );
      case "disabled":
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-zinc-800 text-zinc-400 border border-zinc-700">
            Disabled
          </span>
        );
      default:
        return (
          <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-500/10 text-red-400 border border-red-500/20">
            Unhealthy
          </span>
        );
    }
  };

  return (
    <main className="flex-1 bg-[#0a0a0a] text-zinc-100 flex flex-col items-center justify-center p-6 md:p-12 font-sans selection:bg-emerald-500 selection:text-black">
      <div className="w-full max-w-4xl flex flex-col gap-8">
        <BreadcrumbNav />

        {/* Top Header */}
        <header className="flex justify-between items-center border-b border-zinc-800/80 pb-6">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center">
              <Activity className="h-5 w-5 text-emerald-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-white">System health status</h1>
              <p className="text-sm text-zinc-400">Nexustock modular monolith dashboard</p>
            </div>
          </div>
          <Button
            onClick={handleRefresh}
            disabled={refreshing || loading}
            variant="outline"
          >
            <RefreshCw className={`h-4 w-4 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </header>

        {/* Overview Status Grid */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-6">

          {/* API Web Host */}
          <div className="bg-[#111] border border-zinc-800/60 p-6 rounded-xl flex flex-col justify-between min-h-[140px] hover:border-zinc-700 transition-colors">
            <div className="flex justify-between items-start">
              <div className="h-10 w-10 rounded-lg bg-blue-500/10 border border-blue-500/20 flex items-center justify-center">
                <Server className="h-5 w-5 text-blue-400" />
              </div>
              {getStatusBadge(error ? "unhealthy" : (data?.services.api || "healthy"))}
            </div>
            <div className="mt-4">
              <h3 className="text-sm font-medium text-zinc-400">API Web Host</h3>
              <p className="text-xs text-zinc-500 mt-1">Composition root & Middleware</p>
            </div>
          </div>

          {/* Database Server */}
          <div className="bg-[#111] border border-zinc-800/60 p-6 rounded-xl flex flex-col justify-between min-h-[140px] hover:border-zinc-700 transition-colors">
            <div className="flex justify-between items-start">
              <div className="h-10 w-10 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
                <Database className="h-5 w-5 text-emerald-400" />
              </div>
              {getStatusBadge(error ? "unhealthy" : (data?.services.database || "pending"))}
            </div>
            <div className="mt-4">
              <h3 className="text-sm font-medium text-zinc-400">PostgreSQL Database</h3>
              <p className="text-xs text-zinc-500 mt-1">Main operational storage</p>
            </div>
          </div>

          {/* Cache Store */}
          <div className="bg-[#111] border border-zinc-800/60 p-6 rounded-xl flex flex-col justify-between min-h-[140px] hover:border-zinc-700 transition-colors">
            <div className="flex justify-between items-start">
              <div className="h-10 w-10 rounded-lg bg-red-500/10 border border-red-500/20 flex items-center justify-center">
                <Heart className="h-5 w-5 text-red-400" />
              </div>
              {getStatusBadge(error ? "unhealthy" : (data?.services.redis || "disabled"))}
            </div>
            <div className="mt-4">
              <h3 className="text-sm font-medium text-zinc-400">Redis cache</h3>
              <p className="text-xs text-zinc-500 mt-1">Distributed caching (Optional)</p>
            </div>
          </div>

        </section>

        {/* Server Info & Environment */}
        <section className="bg-[#111] border border-zinc-800/60 rounded-xl p-6 flex flex-col gap-4">
          <h2 className="text-lg font-semibold text-white">Metadata details</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">

            <div className="flex justify-between py-2 border-b border-zinc-800/40">
              <span className="text-zinc-400">Environment</span>
              <span className="font-mono text-zinc-300 capitalize">{error ? "Unknown" : (data?.environment || "Development")}</span>
            </div>

            <div className="flex justify-between py-2 border-b border-zinc-800/40">
              <span className="text-zinc-400">API version</span>
              <span className="font-mono text-zinc-300">{error ? "—" : (data?.version || "0.1.0")}</span>
            </div>

            <div className="flex justify-between py-2 border-b border-zinc-800/40 md:border-none">
              <span className="text-zinc-400">Liveness check (/health/live)</span>
              <span className="font-mono text-emerald-400 flex items-center gap-1.5">
                {getStatusIcon(error ? "unhealthy" : "healthy")} Alive
              </span>
            </div>

            <div className="flex justify-between py-2 border-b border-zinc-800/40 md:border-none">
              <span className="text-zinc-400">Readiness check (/health/ready)</span>
              <span className="font-mono text-yellow-400 flex items-center gap-1.5">
                {getStatusIcon(error ? "unhealthy" : "pending")} Active
              </span>
            </div>

          </div>

          {/* Trace ID */}
          <div className="mt-4 pt-4 border-t border-zinc-800/60 flex flex-col sm:flex-row sm:justify-between gap-2 text-xs text-zinc-500">
            <span>Trace identifier: <span className="font-mono text-zinc-400">{error ? "N/A" : (data?.traceId || "—")}</span></span>
            <span>Last checked: {mounted ? new Date().toLocaleTimeString() : "—"}</span>
          </div>

        </section>

        {/* Global Error Banner */}
        {error && (
          <section className="bg-red-500/10 border border-red-500/25 rounded-xl p-4 flex gap-3 items-center">
            <XCircle className="h-5 w-5 text-red-500 shrink-0" />
            <div>
              <h4 className="text-sm font-semibold text-red-400">API connection error</h4>
              <p className="text-xs text-red-300/80 mt-0.5">{error}</p>
            </div>
          </section>
        )}

      </div>
    </main>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import BreadcrumbNav from "@/components/breadcrumb-nav";
import api from "@/lib/api";
import { showError, showSuccess, showWarning } from "@/lib/toast";

interface ImportRowErrorDto {
  rowIndex: number;
  raw: Record<string, string>;
  errorMessage: string;
}

interface ImportResultDto {
  success: boolean;
  batchId: string;
  importType: string;
  status: string;
  totalRows: number;
  successRows: number;
  errorRows: number;
  errors: ImportRowErrorDto[];
}

export default function ImportPage() {
  const [importType, setImportType] = useState("ITEMS");
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ImportResultDto | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setResult(null);
    }
  };

  const handlePreview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await api.post<ImportResultDto>(`/master-data/imports/preview?importType=${importType}`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setResult(res.data);
      if (res.data.success) {
        showSuccess("Kiểm tra dữ liệu thành công, sẵn sàng duyệt nhập.");
      } else {
        showWarning(`Phát hiện ${res.data.errorRows} dòng dữ liệu lỗi.`);
      }
    } catch (err: any) {
      showError(err.response?.data?.message || "Không thể tải lên file.");
    } finally {
      setLoading(false);
    }
  };

  const handleCommit = async () => {
    if (!result) return;
    setLoading(true);

    try {
      await api.post("/master-data/imports/commit", { batchId: result.batchId });
      showSuccess("Duyệt nhập dữ liệu thành công.");
      setResult(null);
      setFile(null);
    } catch (err: any) {
      showError(err.response?.data?.message || "Duyệt nhập dữ liệu thất bại.");
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadErrors = () => {
    if (!result) return;
    window.open(`http://localhost:5024/api/master-data/imports/${result.batchId}/errors`);
  };

  return (
    <div className="max-w-4xl">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-white/90">Nhập dữ liệu</h1>
        <p className="text-xs text-white/40 mt-1">Hỗ trợ tải lên file CSV để import dữ liệu Master Data nhanh chóng.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
        <div className="bg-[#111] border border-[#222] p-4 rounded-lg text-xs text-white/60">
          <span className="font-semibold text-white/90 block mb-1">Cấu trúc file ITEMS (Vật tư):</span>
          <code>code, name, baseUomCode, shelfLifeDays, minStock</code>
        </div>
        <div className="bg-[#111] border border-[#222] p-4 rounded-lg text-xs text-white/60">
          <span className="font-semibold text-white/90 block mb-1">Cấu trúc file LOCATIONS (Vị trí kệ):</span>
          <code>warehouseCode, zoneCode, code, xCoord, yCoord, zCoord, maxCapacity</code>
        </div>
        <div className="bg-[#111] border border-[#222] p-4 rounded-lg text-xs text-white/60">
          <span className="font-semibold text-white/90 block mb-1">Cấu trúc file PARTNERS (Đối tác):</span>
          <code>code, name, partnerType, address, taxCode</code>
        </div>
      </div>

      <div className="bg-[#111] border border-[#222] p-6 rounded-lg mb-6">
        <form onSubmit={handlePreview} className="flex flex-col gap-4">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <label className="block text-xs font-semibold text-white/40 uppercase tracking-wider mb-2">Loại master data</label>
              <select
                className="w-full bg-[#1a1a1a] border border-[#333] rounded-md px-3 py-2 text-sm text-white/95 focus:outline-none focus:border-[#555]"
                value={importType}
                onChange={(e) => setImportType(e.target.value)}
              >
                <option value="ITEMS">Sản phẩm (ITEMS)</option>
                <option value="LOCATIONS">Vị trí kệ (LOCATIONS)</option>
                <option value="PARTNERS">Đối tác (PARTNERS)</option>
              </select>
            </div>
            <div className="flex-1">
              <label className="block text-xs font-semibold text-white/40 uppercase tracking-wider mb-2">Chọn file CSV</label>
              <input
                type="file"
                accept=".csv"
                onChange={handleFileChange}
                className="w-full bg-[#1a1a1a] border border-[#333] rounded-md px-3 py-1.5 text-sm text-white/80 file:mr-4 file:py-0.5 file:px-2.5 file:rounded-md file:border-0 file:text-xs file:bg-[#333] file:text-white hover:file:bg-[#444]"
              />
            </div>
          </div>
          <Button
            type="submit"
            disabled={loading || !file}
            className="self-start"
          >
            Tải lên kiểm tra (Preview)
          </Button>
        </form>
      </div>

      {loading && <p className="text-white/40 text-sm mb-6">Đang xử lý dữ liệu...</p>}

      {result && (
        <div className="bg-[#111] border border-[#222] p-6 rounded-lg">
          <h2 className="text-lg font-bold text-white/90 mb-4">Kết quả kiểm tra (Batch ID: {result.batchId.slice(0, 8)})</h2>
          <div className="grid grid-cols-3 gap-4 mb-6">
            <div className="p-3 bg-[#1a1a1a] border border-[#222] rounded-md">
              <span className="text-xs text-white/40 block">Tổng số dòng</span>
              <span className="text-xl font-bold text-white">{result.totalRows}</span>
            </div>
            <div className="p-3 bg-[#1a1a1a] border border-[#222] rounded-md">
              <span className="text-xs text-white/40 block">Hợp lệ</span>
              <span className="text-xl font-bold text-green-400">{result.successRows}</span>
            </div>
            <div className="p-3 bg-[#1a1a1a] border border-[#222] rounded-md">
              <span className="text-xs text-white/40 block">Lỗi</span>
              <span className="text-xl font-bold text-red-400">{result.errorRows}</span>
            </div>
          </div>

          {result.errorRows > 0 ? (
            <div>
              <div className="flex items-center justify-between mb-3">
                <span className="text-sm font-semibold text-white/80">Chi tiết lỗi dòng</span>
                <Button
                  onClick={handleDownloadErrors}
                  variant="destructive"
                  size="sm"
                >
                  Tải file lỗi (CSV)
                </Button>
              </div>
              <div className="max-h-60 overflow-y-auto border border-[#222] rounded-md">
                <table className="w-full text-xs text-left">
                  <thead className="bg-[#1a1a1a] text-white/40 uppercase">
                    <tr>
                      <th className="p-2 w-16">Dòng</th>
                      <th className="p-2">Chi tiết dữ liệu</th>
                      <th className="p-2">Thông báo lỗi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#222] text-white/80">
                    {result.errors.map((err) => (
                      <tr key={err.rowIndex} className="hover:bg-[#1a1a1a]">
                        <td className="p-2 font-mono">{err.rowIndex}</td>
                        <td className="p-2 max-w-xs truncate">{JSON.stringify(err.raw)}</td>
                        <td className="p-2 text-red-400">{err.errorMessage}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ) : (
            <Button
              onClick={handleCommit}
              disabled={loading}
            >
              Duyệt import vào hệ thống (Commit)
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import MobileShell from "@/components/mobile/mobile-shell";
import ScanInput from "@/components/mobile/scan-input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { showError, showSuccess } from "@/lib/toast";
import api from "@/lib/api";
import { ArrowLeft, Box, ClipboardCheck, ArrowRight, RefreshCw, Layers } from "lucide-react";
import Link from "next/link";

interface Lpn {
  id: string;
  lpnNo: string;
  locationId: string;
  status: string;
  createdAt: string;
}

interface LpnItem {
  id: string;
  itemCode: string;
  itemName: string;
  lotNo: string;
  qtyOnHand: number;
}

export default function MobileLpnPage() {
  const [lpn, setLpn] = useState<Lpn | null>(null);
  const [lpnItems, setLpnItems] = useState<LpnItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState<"SCAN_LPN" | "SCAN_TARGET_LOC" | "CONFIRM">("SCAN_LPN");

  const [targetLocation, setTargetLocation] = useState<any>(null);
  const [targetLocationCode, setTargetLocationCode] = useState("");
  const [operatorName, setOperatorName] = useState("");

  const handleScanLpn = async (barcode: string) => {
    setLoading(true);
    try {
      // 1. Tìm LPN theo mã quét
      const lpnsRes = await api.get<Lpn[]>("/lpns");
      const matchedLpn = lpnsRes.data.find(
        (l) => l.lpnNo.toUpperCase() === barcode.toUpperCase()
      );

      if (!matchedLpn) {
        showError(`Không tìm thấy Pallet / LPN có mã: ${barcode}`);
        return;
      }

      setLpn(matchedLpn);

      // 2. Load các items trên LPN
      const itemsRes = await api.get<{ items: LpnItem[] }>("/inventory/balances", {
        params: { lpnId: matchedLpn.id }
      });
      setLpnItems(itemsRes.data?.items || []);

      showSuccess("Quét mã LPN thành công!");
      setCurrentStep("SCAN_TARGET_LOC");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi khi kiểm tra mã LPN.");
    } finally {
      setLoading(false);
    }
  };

  const handleScanTargetLocation = async (barcode: string) => {
    setLoading(true);
    try {
      // 1. Kiểm tra vị trí kệ đích có hợp lệ không
      const locsRes = await api.get<{ items: any[] }>("/master-data/storage-locations");
      const matchedLoc = (locsRes.data.items || []).find(
        (l: any) => l.code.toUpperCase() === barcode.toUpperCase()
      );

      if (!matchedLoc) {
        showError(`Không tìm thấy vị trí kệ: ${barcode}`);
        return;
      }

      if (lpn && matchedLoc.id === lpn.locationId) {
        showError("Kệ đích phải khác vị trí hiện tại của LPN.");
        return;
      }

      setTargetLocation(matchedLoc);
      setTargetLocationCode(barcode);
      showSuccess("Quét kệ đích thành công!");
      setCurrentStep("CONFIRM");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi kiểm tra kệ đích.");
    } finally {
      setLoading(false);
    }
  };

  const handleConfirmMove = async () => {
    if (!lpn || !targetLocation) return;

    setLoading(true);
    try {
      await api.post(`/lpns/${lpn.id}/move`, {
        targetLocationId: targetLocation.id
      });

      showSuccess(`Đã di chuyển pallet ${lpn.lpnNo} thành công!`);
      // Reset
      setLpn(null);
      setLpnItems([]);
      setTargetLocation(null);
      setTargetLocationCode("");
      setCurrentStep("SCAN_LPN");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi dịch chuyển pallet.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <MobileShell>
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Link href="/mobile" className="text-slate-300 hover:text-white p-2">
            <ArrowLeft className="h-4 w-4" />
          </Link>
          <h2 className="text-lg font-bold flex items-center gap-2 text-slate-100">
            <Layers className="h-5 w-5 text-emerald-500" />
            Di chuyển Pallet LPN
          </h2>
        </div>

        {currentStep === "SCAN_LPN" && (
          <div className="space-y-4 py-8">
            <div className="text-center space-y-2">
              <Box className="h-12 w-12 text-slate-600 mx-auto animate-bounce" />
              <h3 className="text-base font-semibold text-slate-200">Quét Pallet / LPN</h3>
              <p className="text-xs text-slate-400">Vui lòng quét mã barcode LPN để bắt đầu dịch chuyển nguyên khối</p>
            </div>
            <ScanInput id="lpnBarcodeScan" label="Quét mã LPN" onScan={handleScanLpn} placeholder="Quét LPN..." />
          </div>
        )}

        {lpn && (
          <Card className="border-slate-800 bg-slate-800/40">
            <CardHeader className="pb-2 border-b border-slate-800/80">
              <CardTitle className="text-xs font-semibold text-slate-200">Pallet: {lpn.lpnNo}</CardTitle>
            </CardHeader>
            <CardContent className="p-4 space-y-4">
              {/* LPN Items list */}
              <div className="bg-slate-900/60 p-3 rounded text-xs space-y-1.5 border border-slate-800 max-h-[150px] overflow-y-auto">
                <span className="text-[10px] text-slate-500 block border-b border-slate-800 pb-1">Mặt hàng trên pallet:</span>
                {lpnItems.length === 0 ? (
                  <div className="text-slate-400 italic text-center py-2">Pallet trống</div>
                ) : (
                  lpnItems.map((item, idx) => (
                    <div key={idx} className="flex justify-between text-[11px] text-slate-200">
                      <span>{item.itemCode} (Lô: {item.lotNo})</span>
                      <span className="font-bold text-white">{item.qtyOnHand}</span>
                    </div>
                  ))
                )}
              </div>

              {currentStep === "SCAN_TARGET_LOC" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-850 p-3 rounded text-center border border-amber-500/20">
                    <span className="text-xs text-slate-400 block">Bước 2: Quét mã vị trí kệ đích:</span>
                  </div>
                  <ScanInput id="targetLocationScan" label="Quét kệ đích" onScan={handleScanTargetLocation} placeholder="Quét kệ đích..." />
                </div>
              )}

              {currentStep === "CONFIRM" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-850 p-4 rounded text-center border border-emerald-500/20 space-y-2">
                    <span className="text-xs text-slate-400 block">Xác nhận di chuyển pallet:</span>
                    <span className="text-lg font-bold font-mono text-emerald-400 block">{lpn.lpnNo}</span>
                    <div className="flex items-center justify-center gap-3 text-xs text-white pt-1">
                      <span className="font-mono text-zinc-400">Vị trí cũ</span>
                      <ArrowRight className="h-3.5 w-3.5 text-emerald-500" />
                      <span className="font-mono text-emerald-400 font-bold">{targetLocationCode}</span>
                    </div>
                  </div>

                  <Button onClick={handleConfirmMove} disabled={loading} className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 rounded-lg shadow-lg">
                    {loading ? "Đang xử lý..." : "Xác nhận di chuyển"}
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </MobileShell>
  );
}

