"use client";

import { useEffect, useState } from "react";
import MobileShell from "@/components/mobile/mobile-shell";
import ScanInput from "@/components/mobile/scan-input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { showError, showSuccess } from "@/lib/toast";
import api from "@/lib/api";
import { ArrowLeft, Move, RefreshCw } from "lucide-react";
import Link from "next/link";

interface OfflineMove {
  clientOperationId: string;
  stepType: string;
  payload: string;
}

export default function MovementPage() {
  const [loading, setLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(true);
  const [offlineQueue, setOfflineQueue] = useState<OfflineMove[]>([]);

  // Form State
  const [fromLoc, setFromLoc] = useState("");
  const [lotNo, setLotNo] = useState("");
  const [toLoc, setToLoc] = useState("");
  const [qty, setQty] = useState("");

  const [currentStep, setCurrentStep] = useState<"SCAN_FROM" | "SCAN_LOT" | "INPUT_QTY" | "SCAN_TO" | "CONFIRM">("SCAN_FROM");

  useEffect(() => {
    setIsOnline(navigator.onLine);
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    // Load offline queue from LocalStorage
    const stored = localStorage.getItem("nexustock_offline_movements");
    if (stored) {
      setOfflineQueue(JSON.parse(stored));
    }

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  const saveOfflineQueue = (newQueue: OfflineMove[]) => {
    setOfflineQueue(newQueue);
    localStorage.setItem("nexustock_offline_movements", JSON.stringify(newQueue));
  };

  const handleScanFrom = async (barcode: string) => {
    setLoading(true);
    try {
      if (isOnline) {
        await api.post("/mobile/scan/validate", { barcode, context: "LOCATION" });
      }
      setFromLoc(barcode);
      showSuccess("Đã quét vị trí nguồn.");
      setCurrentStep("SCAN_LOT");
    } catch (err: any) {
      showError(err.response?.data?.message || "Vị trí không hợp lệ hoặc bị khóa!");
    } finally {
      setLoading(false);
    }
  };

  const handleScanLot = async (barcode: string) => {
    setLoading(true);
    try {
      if (isOnline) {
        await api.post("/mobile/scan/validate", { barcode, context: "LOT" });
      }
      setLotNo(barcode);
      showSuccess("Đã quét số lô.");
      setCurrentStep("INPUT_QTY");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lô hàng không tồn tại!");
    } finally {
      setLoading(false);
    }
  };

  const handleInputQty = () => {
    const parsed = parseFloat(qty);
    if (isNaN(parsed) || parsed <= 0) {
      showError("Số lượng dịch chuyển phải lớn hơn 0");
      return;
    }
    setCurrentStep("SCAN_TO");
  };

  const handleScanTo = async (barcode: string) => {
    if (barcode === fromLoc) {
      showError("Vị trí đích không được trùng vị trí nguồn");
      return;
    }
    setLoading(true);
    try {
      if (isOnline) {
        await api.post("/mobile/scan/validate", { barcode, context: "LOCATION" });
      }
      setToLoc(barcode);
      showSuccess("Đã quét vị trí đích.");
      setCurrentStep("CONFIRM");
    } catch (err: any) {
      showError(err.response?.data?.message || "Vị trí đích không hợp lệ!");
    } finally {
      setLoading(false);
    }
  };

  const handleConfirmMovement = async () => {
    const parsedQty = parseFloat(qty);
    const payloadData = {
      itemId: "00000000-0000-0000-0000-000000000001", // Giả định ID vật tư mẫu cho phase scan core
      lotNo,
      fromLocationCode: fromLoc,
      toLocationCode: toLoc,
      qty: parsedQty
    };

    const clientOperationId = `OP-MOVE-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    if (!isOnline) {
      // Lưu offline
      const newOp: OfflineMove = {
        clientOperationId,
        stepType: "MOVE",
        payload: JSON.stringify(payloadData)
      };
      const updatedQueue = [...offlineQueue, newOp];
      saveOfflineQueue(updatedQueue);
      showSuccess("Mất mạng. Đã lưu nhiệm vụ vào hàng đợi ngoại tuyến thành công!");
      resetForm();
      return;
    }

    setLoading(true);
    try {
      // Gọi trực tiếp đồng bộ online
      await api.post("/mobile/offline-sync", {
        operations: [
          {
            clientOperationId,
            stepType: "MOVE",
            payload: JSON.stringify(payloadData)
          }
        ]
      });
      showSuccess("Thực hiện dịch chuyển kho thành công!");
      resetForm();
    } catch (err: any) {
      showError(err.response?.data?.message || "Dịch chuyển kho thất bại!");
    } finally {
      setLoading(false);
    }
  };

  const handleSyncOfflineQueue = async () => {
    if (offlineQueue.length === 0) return;
    setLoading(true);
    try {
      await api.post("/mobile/offline-sync", { operations: offlineQueue });
      showSuccess("Đồng bộ toàn bộ dữ liệu offline thành công!");
      saveOfflineQueue([]);
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi đồng bộ dữ liệu ngoại tuyến.");
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFromLoc("");
    setLotNo("");
    setToLoc("");
    setQty("");
    setCurrentStep("SCAN_FROM");
  };

  return (
    <MobileShell>
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="icon" asChild className="text-slate-300">
              <Link href="/mobile">
                <ArrowLeft className="h-4 w-4" />
              </Link>
            </Button>
            <h2 className="text-lg font-bold flex items-center gap-2 text-slate-100">
              <Move className="h-5 w-5 text-blue-500" />
              Dịch chuyển kho (Movement)
            </h2>
          </div>

          {offlineQueue.length > 0 && isOnline && (
            <Button onClick={handleSyncOfflineQueue} disabled={loading} size="sm" variant="outline" className="border-yellow-500 text-yellow-500 hover:bg-yellow-500/10 gap-2">
              <RefreshCw className="h-3.5 w-3.5 animate-spin" />
              Đồng bộ ({offlineQueue.length})
            </Button>
          )}
        </div>

        <Card className="border-slate-800 bg-slate-800/40">
          <CardContent className="p-4 space-y-4">
            <div className="space-y-2 text-xs font-mono text-slate-400 border-b border-slate-800/60 pb-3">
              <div>Vị trí nguồn: <span className="text-white font-bold">{fromLoc || "—"}</span></div>
              <div>Số lô hàng: <span className="text-white font-bold">{lotNo || "—"}</span></div>
              <div>Số lượng chuyển: <span className="text-white font-bold">{qty || "—"}</span></div>
              <div>Vị trí đích: <span className="text-white font-bold">{toLoc || "—"}</span></div>
            </div>

            {currentStep === "SCAN_FROM" && (
              <ScanInput id="fromLocScan" label="Bước 1: Quét vị trí kệ nguồn" onScan={handleScanFrom} placeholder="Quét vị trí nguồn..." />
            )}

            {currentStep === "SCAN_LOT" && (
              <ScanInput id="lotScan" label="Bước 2: Quét mã số lô sản phẩm" onScan={handleScanLot} placeholder="Quét số lô cần chuyển..." />
            )}

            {currentStep === "INPUT_QTY" && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="moveQty" className="text-sm font-semibold text-slate-300">Bước 3: Nhập số lượng dịch chuyển</Label>
                  <Input
                    id="moveQty"
                    type="number"
                    step="any"
                    value={qty}
                    onChange={(e) => setQty(e.target.value)}
                    placeholder="Nhập số lượng..."
                    className="bg-slate-800 border-slate-700 text-white font-mono text-lg"
                  />
                </div>
                <Button onClick={handleInputQty} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold">
                  Tiếp theo
                </Button>
              </div>
            )}

            {currentStep === "SCAN_TO" && (
              <ScanInput id="toLocScan" label="Bước 4: Quét vị trí kệ đích" onScan={handleScanTo} placeholder="Quét vị trí đích..." />
            )}

            {currentStep === "CONFIRM" && (
              <div className="space-y-4 pt-2">
                <div className="bg-slate-850 p-4 rounded text-sm space-y-2 text-slate-200 border border-slate-700">
                  <div className="text-center font-bold text-base text-blue-400 mb-2">Xác nhận dịch chuyển</div>
                  <div>Từ kệ: <span className="font-bold text-white font-mono">{fromLoc}</span></div>
                  <div>Đến kệ: <span className="font-bold text-white font-mono">{toLoc}</span></div>
                  <div>Lô hàng: <span className="font-bold text-white font-mono">{lotNo}</span></div>
                  <div>Số lượng: <span className="font-bold text-emerald-400 font-mono">{qty}</span></div>
                </div>

                <div className="flex gap-2">
                  <Button onClick={resetForm} variant="outline" className="flex-1 border-slate-700 text-slate-300">
                    Làm lại
                  </Button>
                  <Button onClick={handleConfirmMovement} disabled={loading} className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold">
                    {loading ? "Đang xử lý..." : isOnline ? "Xác nhận chuyển" : "Lưu offline"}
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </MobileShell>
  );
}

"use client";

import { useState } from "react";
import MobileShell from "@/components/mobile/mobile-shell";
import ScanInput from "@/components/mobile/scan-input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { showError, showSuccess } from "@/lib/toast";
import api from "@/lib/api";
import { ArrowLeft, Box, ClipboardCheck, ArrowRight } from "lucide-react";
import Link from "next/link";

interface Task {
  id: string;
  referenceType: string;
  referenceId: string;
  step: string;
  locationId: string;
  assignedUser: string;
  status: string;
}

export default function PickingPage() {
  const [task, setTask] = useState<Task | null>(null);
  const [loading, setLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState<"CLAIM" | "SCAN_LOC" | "SCAN_LOT" | "INPUT_QTY" | "COMPLETE">("CLAIM");

  // Vị trí khai báo hiện tại của user để tối ưu hóa gợi ý task
  const [userLocation, setUserLocation] = useState("");

  const handleClaimNextTask = async () => {
    setLoading(true);
    try {
      const res = await api.get<{ task: Task; message: string }>("/mobile/tasks/next", {
        params: { currentLocationCode: userLocation }
      });
      if (res.data.task) {
        setTask(res.data.task);
        setCurrentStep("SCAN_LOC");
        showSuccess(res.data.message);
      } else {
        showError(res.data.message || "Không có nhiệm vụ nào sẵn sàng.");
      }
    } catch (err: any) {
      showError(err.response?.data?.message || "Không thể lấy nhiệm vụ mới.");
    } finally {
      setLoading(false);
    }
  };

  const handleScanLocation = async (barcode: string) => {
    setLoading(true);
    try {
      await api.post("/mobile/scan/validate", { barcode, context: "LOCATION" });
      setUserLocation(barcode); // Cập nhật vị trí hiện tại
      showSuccess("Xác nhận vị trí kệ thành công!");
      setCurrentStep("SCAN_LOT");
    } catch (err: any) {
      showError(err.response?.data?.message || "Vị trí kệ không hợp lệ!");
    } finally {
      setLoading(false);
    }
  };

  const handleScanLot = async (barcode: string) => {
    setLoading(true);
    try {
      await api.post("/mobile/scan/validate", { barcode, context: "LOT" });
      showSuccess("Xác nhận số lô hàng thành công!");
      setCurrentStep("INPUT_QTY");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lô hàng không tồn tại trong kho!");
    } finally {
      setLoading(false);
    }
  };

  const handleCompleteTask = async () => {
    if (!task) return;
    setLoading(true);
    try {
      await api.post(`/mobile/tasks/${task.id}/complete`);
      showSuccess("Hoàn thành nhiệm vụ lấy hàng!");
      setTask(null);
      setCurrentStep("CLAIM");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi hoàn tất nhiệm vụ.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <MobileShell>
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="icon" asChild className="text-slate-300">
            <Link href="/mobile">
              <ArrowLeft className="h-4 w-4" />
            </Link>
          </Button>
          <h2 className="text-lg font-bold flex items-center gap-2 text-slate-100">
            <ClipboardCheck className="h-5 w-5 text-orange-500" />
            Lấy hàng xuất kho (Picking)
          </h2>
        </div>

        {currentStep === "CLAIM" && (
          <div className="space-y-4 py-8">
            <div className="text-center space-y-2">
              <Box className="h-12 w-12 text-slate-600 mx-auto animate-bounce" />
              <h3 className="text-base font-semibold text-slate-200">Sẵn sàng nhận nhiệm vụ</h3>
              <p className="text-xs text-slate-400">Hệ thống sẽ tự động giao việc có vị trí kệ gần nhất với bạn</p>
            </div>

            <div className="space-y-2">
              <label htmlFor="userLoc" className="text-xs text-slate-400 block">Khai báo vị trí hiện tại của bạn (Tùy chọn):</label>
              <input
                id="userLoc"
                type="text"
                value={userLocation}
                onChange={(e) => setUserLocation(e.target.value.toUpperCase())}
                placeholder="Ví dụ: LOC-A-01"
                className="w-full bg-slate-800 border border-slate-700 rounded p-2 text-white font-mono text-sm text-center"
              />
            </div>

            <Button onClick={handleClaimNextTask} disabled={loading} className="w-full bg-orange-600 hover:bg-orange-700 text-white py-6 text-base font-bold rounded-lg shadow-lg gap-2">
              <ArrowRight className="h-5 w-5" />
              {loading ? "Đang nhận việc..." : "Nhận việc tiếp theo"}
            </Button>
          </div>
        )}

        {task && (
          <Card className="border-slate-800 bg-slate-800/40">
            <CardHeader className="pb-2 border-b border-slate-800/80">
              <CardTitle className="text-sm font-semibold text-slate-200">Nhiệm vụ đang làm</CardTitle>
            </CardHeader>
            <CardContent className="p-4 space-y-4">
              <div className="grid grid-cols-2 gap-2 text-xs font-mono text-slate-300">
                <div>Loại: <span className="text-orange-500 font-bold">{task.referenceType}</span></div>
                <div>ID Đơn: <span className="text-white">{task.referenceId.substring(0, 8)}</span></div>
                <div className="col-span-2">Bước: <span className="text-white font-bold">{task.step}</span></div>
              </div>

              {currentStep === "SCAN_LOC" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-800/80 p-3 rounded text-center border border-orange-500/25">
                    <span className="text-xs text-slate-400 block">Yêu cầu di chuyển đến vị trí kệ và quét:</span>
                    <span className="text-lg font-bold font-mono text-orange-500">LOC-A-01</span>
                  </div>
                  <ScanInput id="locScan" label="Quét mã vị trí kệ" onScan={handleScanLocation} placeholder="Quét LOC-A-01..." />
                </div>
              )}

              {currentStep === "SCAN_LOT" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-800/80 p-3 rounded text-center border border-orange-500/25">
                    <span className="text-xs text-slate-400 block">Yêu cầu quét mã số lô sản phẩm:</span>
                    <span className="text-base font-bold font-mono text-white">LOT-CC-1783908121977</span>
                  </div>
                  <ScanInput id="lotScan" label="Quét mã số lô" onScan={handleScanLot} placeholder="Quét LOT-CC..." />
                </div>
              )}

              {currentStep === "INPUT_QTY" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-800/80 p-3 rounded text-center border border-orange-500/25">
                    <span className="text-xs text-slate-400 block">Số lượng cần lấy:</span>
                    <span className="text-2xl font-bold font-mono text-emerald-400">10 sản phẩm</span>
                  </div>

                  <Button onClick={handleCompleteTask} disabled={loading} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-4 rounded-lg">
                    Xác nhận hoàn thành lấy hàng
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </MobileShell>
  );
}

"use client";

import { useState } from "react";
import MobileShell from "@/components/mobile/mobile-shell";
import ScanInput from "@/components/mobile/scan-input";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { showError, showSuccess } from "@/lib/toast";
import api from "@/lib/api";
import { ArrowLeft, Box, ClipboardCheck, ArrowRight, RefreshCw } from "lucide-react";
import Link from "next/link";

interface MobileTask {
  id: string;
  referenceType: string;
  referenceId: string;
  step: string;
  locationId: string;
  assignedUser: string;
  status: string;
}

interface ReplenishmentTaskDetail {
  id: string;
  itemId: string;
  itemCode: string;
  itemName: string;
  sourceLocationId: string;
  sourceLocationCode: string;
  targetLocationId: string;
  targetLocationCode: string;
  lotNo: string;
  requestedQty: number;
}

export default function MobileReplenishmentPage() {
  const [mobileTask, setMobileTask] = useState<MobileTask | null>(null);
  const [taskDetail, setTaskDetail] = useState<ReplenishmentTaskDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState<"CLAIM" | "SCAN_SOURCE_LOC" | "SCAN_LOT" | "SCAN_TARGET_LOC" | "INPUT_QTY">("CLAIM");

  const [userLocation, setUserLocation] = useState("");
  const [actualQty, setActualQty] = useState<number>(0);
  const [operatorName, setOperatorName] = useState("");

  const handleClaimNextTask = async () => {
    setLoading(true);
    try {
      // 1. Claim next task từ Mobile task pool
      const res = await api.get<{ task: MobileTask; message: string }>("/mobile/tasks/next", {
        params: { currentLocationCode: userLocation }
      });

      if (res.data.task) {
        const claimedTask = res.data.task;

        if (claimedTask.referenceType !== "REPLENISHMENT") {
          // Chỉ nhận nhiệm vụ Replenishment
          showError("Nhiệm vụ nhận được không phải là Bổ sung hàng. Vui lòng thử lại.");
          await api.post(`/mobile/tasks/${claimedTask.id}/complete`); // Giải phóng hoặc trả lại
          return;
        }

        setMobileTask(claimedTask);

        // 2. Fetch chi tiết ReplenishmentTask tương ứng
        // Vì API GET /api/replenishment/tasks trả về tất cả, ta lọc theo ID
        const tasksRes = await api.get<any[]>("/replenishment/tasks");
        const detail = tasksRes.data.find((t) => t.id === claimedTask.referenceId);

        if (detail) {
          // Load location codes để hiển thị trực quan
          const locsRes = await api.get<any[]>("/masterdata/locations");
          const sourceLoc = locsRes.data.find((l) => l.id === detail.sourceLocationId);
          const targetLoc = locsRes.data.find((l) => l.id === detail.targetLocationId);

          // Load sản phẩm
          const prodsRes = await api.get<any[]>("/masterdata/products");
          const prod = prodsRes.data.find((p) => p.id === detail.itemId);

          setTaskDetail({
            id: detail.id,
            itemId: detail.itemId,
            itemCode: prod?.code || "",
            itemName: prod?.name || "",
            sourceLocationId: detail.sourceLocationId,
            sourceLocationCode: sourceLoc?.code || detail.sourceLocationId.substring(0, 8),
            targetLocationId: detail.targetLocationId,
            targetLocationCode: targetLoc?.code || detail.targetLocationId.substring(0, 8),
            lotNo: detail.lotNo,
            requestedQty: detail.requestedQty
          });

          setActualQty(detail.requestedQty);
          setCurrentStep("SCAN_SOURCE_LOC");
          showSuccess("Đã nhận việc bổ sung hàng thành công!");
        } else {
          showError("Không tìm thấy chi tiết nhiệm vụ bổ sung.");
          setMobileTask(null);
        }
      } else {
        showError(res.data.message || "Không còn nhiệm vụ bổ sung nào sẵn sàng.");
      }
    } catch (err: any) {
      showError(err.response?.data?.message || "Không thể lấy nhiệm vụ mới.");
    } finally {
      setLoading(false);
    }
  };

  const handleScanSourceLocation = async (barcode: string) => {
    if (!taskDetail) return;
    if (barcode.toUpperCase() !== taskDetail.sourceLocationCode.toUpperCase()) {
      showError(`Mã vị trí không khớp! Vui lòng quét đúng kệ nguồn: ${taskDetail.sourceLocationCode}`);
      return;
    }

    setLoading(true);
    try {
      await api.post("/mobile/scan/validate", { barcode, context: "LOCATION" });
      setUserLocation(barcode);
      showSuccess("Đã xác nhận kệ nguồn thành công!");
      setCurrentStep("SCAN_LOT");
    } catch (err: any) {
      showError(err.response?.data?.message || "Vị trí kệ nguồn không hợp lệ!");
    } finally {
      setLoading(false);
    }
  };

  const handleScanLot = async (barcode: string) => {
    if (!taskDetail) return;
    if (barcode !== taskDetail.lotNo) {
      showError(`Mã số lô sản phẩm không khớp! Vui lòng quét đúng số lô: ${taskDetail.lotNo}`);
      return;
    }

    setLoading(true);
    try {
      await api.post("/mobile/scan/validate", { barcode, context: "LOT" });
      showSuccess("Đã xác nhận số lô sản phẩm thành công!");
      setCurrentStep("SCAN_TARGET_LOC");
    } catch (err: any) {
      showError(err.response?.data?.message || "Mã số lô sản phẩm không hợp lệ!");
    } finally {
      setLoading(false);
    }
  };

  const handleScanTargetLocation = async (barcode: string) => {
    if (!taskDetail) return;
    if (barcode.toUpperCase() !== taskDetail.targetLocationCode.toUpperCase()) {
      showError(`Mã vị trí không khớp! Vui lòng quét đúng kệ đích: ${taskDetail.targetLocationCode}`);
      return;
    }

    setLoading(true);
    try {
      await api.post("/mobile/scan/validate", { barcode, context: "LOCATION" });
      showSuccess("Đã xác nhận kệ đích Pick Face thành công!");
      setCurrentStep("INPUT_QTY");
    } catch (err: any) {
      showError(err.response?.data?.message || "Vị trí kệ đích không hợp lệ!");
    } finally {
      setLoading(false);
    }
  };

  const handleCompleteTask = async () => {
    if (!mobileTask || !taskDetail) return;
    if (actualQty < 0) {
      showError("Số lượng thực tế phải lớn hơn hoặc bằng 0.");
      return;
    }

    setLoading(true);
    try {
      const payload = {
        actualQty,
        operatorName: operatorName || "Handheld User"
      };
      // Gọi qua API Complete của Replenishment Controller để chạy toàn bộ logic nghiệp vụ
      await api.post(`/replenishment/tasks/${taskDetail.id}/complete`, payload);

      showSuccess("Hoàn thành nhiệm vụ bổ sung hàng thành công!");
      setMobileTask(null);
      setTaskDetail(null);
      setCurrentStep("CLAIM");
    } catch (err: any) {
      showError(err.response?.data?.message || "Gặp lỗi khi hoàn thành nhiệm vụ bổ sung.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <MobileShell>
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="icon" asChild className="text-slate-300">
            <Link href="/mobile">
              <ArrowLeft className="h-4 w-4" />
            </Link>
          </Button>
          <h2 className="text-lg font-bold flex items-center gap-2 text-slate-100">
            <RefreshCw className="h-5 w-5 text-emerald-500" />
            Bổ sung Pick Face
          </h2>
        </div>

        {currentStep === "CLAIM" && (
          <div className="space-y-4 py-8">
            <div className="text-center space-y-2">
              <Box className="h-12 w-12 text-slate-600 mx-auto animate-bounce" />
              <h3 className="text-base font-semibold text-slate-200">Sẵn sàng nhận nhiệm vụ</h3>
              <p className="text-xs text-slate-400">Hệ thống sẽ giao nhiệm vụ bổ sung kệ Pick Face thiếu hụt gần vị trí của bạn nhất</p>
            </div>

            <div className="space-y-2">
              <label htmlFor="userLoc" className="text-xs text-slate-400 block">Khai báo vị trí hiện tại (Tùy chọn):</label>
              <input
                id="userLoc"
                type="text"
                value={userLocation}
                onChange={(e) => setUserLocation(e.target.value.toUpperCase())}
                placeholder="Ví dụ: LOC-A-01"
                className="w-full bg-slate-800 border border-slate-700 rounded p-2 text-white font-mono text-sm text-center"
              />
            </div>

            <Button onClick={handleClaimNextTask} disabled={loading} className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-6 text-base font-bold rounded-lg shadow-lg gap-2">
              <ArrowRight className="h-5 w-5" />
              {loading ? "Đang nhận việc..." : "Nhận việc tiếp theo"}
            </Button>
          </div>
        )}

        {mobileTask && taskDetail && (
          <Card className="border-slate-800 bg-slate-800/40">
            <CardHeader className="pb-2 border-b border-slate-800/80">
              <CardTitle className="text-xs font-semibold text-slate-200">Chi tiết nhiệm vụ bổ sung</CardTitle>
            </CardHeader>
            <CardContent className="p-4 space-y-4">
              <div className="bg-slate-900/60 p-3 rounded text-xs space-y-1.5 border border-slate-800">
                <div>Sản phẩm: <span className="text-white font-bold">{taskDetail.itemCode} - {taskDetail.itemName}</span></div>
                <div>Số lô (Lot): <span className="text-zinc-200 font-bold">{taskDetail.lotNo}</span></div>
                <div className="grid grid-cols-2 gap-2 mt-1 pt-1.5 border-t border-slate-800/60">
                  <div>Kệ Bulk nguồn: <span className="text-amber-500 font-bold font-mono block text-sm">{taskDetail.sourceLocationCode}</span></div>
                  <div>Kệ Pick đích: <span className="text-emerald-500 font-bold font-mono block text-sm">{taskDetail.targetLocationCode}</span></div>
                </div>
              </div>

              {currentStep === "SCAN_SOURCE_LOC" && (
                <div className="space-y-4 pt-2">
                  <div className="bg-slate-850 p-3 rounded text-center border border-amber-500/20">
                    <span className="text-xs text-slate-400 block">Bước 1: Di chuyển đến kệ Bulk nguồn và quét mã:</span>
                    <span className="text-lg font-bold font-mono text-amber-500">{taskDetail.sourceLocationCode}</span>
                  </div>
                  <ScanInput id="sourceLocScan" label="Quét mã vị trí kệ nguồn" onScan={handleScanSourceLocation} placeholder="Quét kệ nguồn..." />
                </div>
              )}

              {currentStep === "SCAN_LOT" && (
                <div className="space-y-4 pt-2">
