                    <span className="text-base font-bold font-mono text-white">{taskDetail.lotNo}</span>
                  </div>
                  <ScanInput id="lotScan" label="Quét mã vạch số lô" onScan={handleScanLot} placeholder="Quét số lô sản phẩm..." />
