"use client";

import { useEffect, useState } from "react";
import api from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { showError, showSuccess } from "@/lib/toast";

interface CompletePickDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  pickTaskId: string;
  itemName: string;
  lotNo: string;
  locationCode: string;
  allocatedQty: number;
}

export function CompletePickDialog({
  isOpen,
  onClose,
  onSuccess,
  pickTaskId,
  itemName,
  lotNo,
  locationCode,
  allocatedQty,
}: CompletePickDialogProps) {
  const [pickedQty, setPickedQty] = useState<number>(allocatedQty);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setPickedQty(allocatedQty);
    }
  }, [isOpen, allocatedQty]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pickedQty <= 0) {
      showError("Số lượng pick phải lớn hơn 0.");
      return;
    }
    if (pickedQty > allocatedQty) {
      showError(`Số lượng pick thực tế không được vượt quá số lượng phân bổ (${allocatedQty}).`);
      return;
    }

    setSaving(true);
    try {
      await api.post(`/outbound/picks/${pickTaskId}/complete`, {
        pickedQty
      });
      showSuccess("Hoàn thành nhiệm vụ lấy hàng.");
      onSuccess();
      onClose();
    } catch (err: any) {
      showError(err.response?.data?.message || "Không thể hoàn tất nhiệm vụ lấy hàng.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[400px]">
        <DialogHeader>
          <DialogTitle>Xác nhận lấy hàng (Picking)</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div className="grid grid-cols-3 items-center gap-4">
            <Label className="text-right">Vật tư</Label>
            <div className="col-span-2 text-sm font-semibold">{itemName}</div>
          </div>
          <div className="grid grid-cols-3 items-center gap-4">
            <Label className="text-right">Số lô</Label>
            <div className="col-span-2 text-sm font-mono font-semibold">{lotNo}</div>
          </div>
          <div className="grid grid-cols-3 items-center gap-4">
            <Label className="text-right">Vị trí kệ</Label>
            <div className="col-span-2 text-sm font-bold text-amber-600">{locationCode}</div>
          </div>
          <div className="grid grid-cols-3 items-center gap-4">
            <Label className="text-right">Yêu cầu pick</Label>
            <div className="col-span-2 text-sm font-semibold">{allocatedQty}</div>
          </div>
          <div className="grid grid-cols-3 items-center gap-4">
            <Label htmlFor="pickedQty" className="text-right">Thực tế pick</Label>
            <Input
              id="pickedQty"
              type="number"
              step="any"
              max={allocatedQty}
              min={0.0001}
              value={pickedQty}
              onChange={(e) => setPickedQty(parseFloat(e.target.value) || 0)}
              className="col-span-2"
              autoFocus
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose} disabled={saving}>Hủy</Button>
            <Button type="submit" disabled={saving}>Xác nhận pick</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import api from "@/lib/api";
import { showError, showSuccess } from "@/lib/toast";

interface HoldReleaseDialogProps {
  isOpen: boolean;
  onClose: () => void;
  lotId: string;
  lotNo: string;
  mode: "hold" | "release" | "reject";
  onSuccess: () => void;
}

export function HoldReleaseDialog({ isOpen, onClose, lotId, lotNo, mode, onSuccess }: HoldReleaseDialogProps) {
  const [reasonCode, setReasonCode] = useState("");
  const [locationId, setLocationId] = useState("");
  const [loading, setLoading] = useState(false);

  const getTitle = () => {
    switch (mode) {
      case "hold":
        return `Khóa lô hàng ${lotNo}`;
      case "release":
        return `Giải phóng lô hàng ${lotNo}`;
      case "reject":
        return `Từ chối lô hàng ${lotNo}`;
    }
  };

  const getButtonText = () => {
    switch (mode) {
      case "hold":
        return "Khóa hàng";
      case "release":
        return "Giải phóng";
      case "reject":
        return "Từ chối";
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reasonCode.trim()) {
      showError("Vui lòng nhập lý do.");
      return;
    }

    setLoading(true);
    try {
      if (mode === "hold") {
        await api.post(`/qc/${lotId}/hold`, {
          locationId: locationId || undefined,
          reasonCode: reasonCode.trim()
        });
        showSuccess("Khóa lô hàng thành công.");
      } else if (mode === "release") {
        await api.post(`/qc/${lotId}/release`, {
          reasonCode: reasonCode.trim()
        });
        showSuccess("Giải phóng lô hàng thành công.");
      } else if (mode === "reject") {
        await api.post(`/qc/${lotId}/reject`, {
          reasonCode: reasonCode.trim()
        });
        showSuccess("Từ chối lô hàng thành công.");
      }
      onSuccess();
      onClose();
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi xử lý yêu cầu.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[425px] bg-zinc-900 border-zinc-800 text-white font-sans">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold text-white">{getTitle()}</DialogTitle>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {mode === "hold" && (
              <div className="grid gap-2">
                <Label htmlFor="locationId" className="text-xs text-zinc-400">Vị trí kệ cụ thể (Không bắt buộc)</Label>
                <Input
                  id="locationId"
                  placeholder="Nhập ID vị trí (nếu muốn khóa cụ thể)"
                  value={locationId}
                  onChange={(e) => setLocationId(e.target.value)}
                  className="bg-zinc-800 border-zinc-700 text-white h-9 text-sm focus:ring-emerald-500"
                />
              </div>
            )}

            <div className="grid gap-2">
              <Label htmlFor="reasonCode" className="text-xs text-zinc-400">Lý do (Reason code)</Label>
              <Input
                id="reasonCode"
                placeholder={mode === "hold" ? "Ví dụ: QC_FAILED, DAMAGE" : "Nhập lý do thực hiện"}
                value={reasonCode}
                onChange={(e) => setReasonCode(e.target.value)}
                required
                className="bg-zinc-800 border-zinc-700 text-white h-9 text-sm focus:ring-emerald-500"
              />
            </div>
          </div>

          <DialogFooter className="gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={loading}
              className="border-zinc-700 text-zinc-300 hover:bg-zinc-800 hover:text-white h-9 text-xs"
            >
              Hủy
            </Button>
            <Button
              type="submit"
              disabled={loading}
              className={`${
                mode === "release"
                  ? "bg-emerald-600 hover:bg-emerald-500"
                  : mode === "reject"
                  ? "bg-rose-600 hover:bg-rose-500"
                  : "bg-amber-600 hover:bg-amber-500"
              } text-white h-9 text-xs`}
            >
              {loading ? "Đang xử lý..." : getButtonText()}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useRef } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import api from "@/lib/api";
import { showError, showSuccess } from "@/lib/toast";
import { Upload, FileText, X, Check, AlertTriangle } from "lucide-react";

interface QcResultDialogProps {
  isOpen: boolean;
  onClose: () => void;
  lotId: string;
  lotNo: string;
  qcRequestId: string;
  onSuccess: () => void;
}

export function QcResultDialog({ isOpen, onClose, lotId, lotNo, qcRequestId, onSuccess }: QcResultDialogProps) {
  const [isPassed, setIsPassed] = useState(true);
  const [metrics, setMetrics] = useState("");
  const [attachmentRefs, setAttachmentRefs] = useState("");
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    setUploading(true);
    try {
      const res = await api.post<{ url: string }>("/storage/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      const uploadedUrl = res.data.url;
      setAttachmentRefs((prev) => (prev ? `${prev},${uploadedUrl}` : uploadedUrl));
      showSuccess("Tải tài liệu lên thành công.");
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi tải tệp lên.");
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const removeAttachment = (urlToRemove: string) => {
    const refs = attachmentRefs.split(",").filter((url) => url !== urlToRemove).join(",");
    setAttachmentRefs(refs);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await api.post(`/qc/${lotId}/result`, {
        qcRequestId,
        isPassed,
        metrics: metrics.trim() || undefined,
        attachmentRefs: attachmentRefs || undefined
      });
      showSuccess("Ghi nhận kết quả QC thành công.");
      onSuccess();
      onClose();
    } catch (err: any) {
      showError(err.response?.data?.message || "Lỗi gửi kết quả QC.");
    } finally {
      setLoading(false);
    }
  };

  const attachmentsList = attachmentRefs ? attachmentRefs.split(",").filter(Boolean) : [];

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[500px] bg-zinc-900 border-zinc-800 text-white font-sans">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold text-white">Kiểm định chất lượng lô {lotNo}</DialogTitle>
          </DialogHeader>

          <div className="grid gap-5 py-4">
            <div className="flex items-center justify-between bg-zinc-800/50 p-3 rounded-lg border border-zinc-850">
              <div>
                <Label className="text-sm font-medium text-white block">Trạng thái kiểm định</Label>
                <span className="text-xs text-zinc-400">
                  {isPassed ? "Lô hàng đạt tiêu chuẩn chất lượng" : "Lô hàng không đạt tiêu chuẩn"}
                </span>
              </div>
              <div className="flex items-center gap-2">
                <span className={`text-xs font-semibold ${isPassed ? "text-emerald-500" : "text-rose-500"}`}>
                  {isPassed ? "Đạt" : "Không đạt"}
                </span>
                <Switch
                  checked={isPassed}
                  onCheckedChange={setIsPassed}
                  className="data-[state=checked]:bg-emerald-600 data-[state=unchecked]:bg-rose-600"
                />
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="metrics" className="text-xs text-zinc-400">Thông số đo lường / Kết quả kiểm tra</Label>
              <Textarea
                id="metrics"
                placeholder="Nhập các thông số đo lường như độ ẩm, kích thước, khối lượng, lỗi phát hiện..."
                value={metrics}
                onChange={(e) => setMetrics(e.target.value)}
                rows={3}
                className="bg-zinc-800 border-zinc-700 text-white text-sm focus:ring-emerald-500"
              />
            </div>

            <div className="grid gap-2">
              <Label className="text-xs text-zinc-400">Tài liệu / Ảnh bằng chứng QC</Label>
              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={uploading}
                  className="border-dashed border-zinc-700 text-zinc-300 hover:bg-zinc-800 hover:text-white h-9 text-xs gap-2 flex-1"
                >
                  <Upload className="h-4 w-4" />
                  {uploading ? "Đang tải tệp lên..." : "Tải tệp đính kèm lên"}
                </Button>
                <input
                  type="file"
                  ref={fileInputRef}
                  onChange={handleFileChange}
                  className="hidden"
                  accept="image/*,application/pdf"
                />
              </div>

              {attachmentsList.length > 0 && (
                <div className="grid grid-cols-2 gap-2 mt-2">
                  {attachmentsList.map((url, i) => {
                    const isImg = /\.(jpg|jpeg|png|webp|gif)$/i.test(url);
                    const filename = url.split("/").pop() || "File";
                    return (
                      <div key={i} className="flex items-center justify-between p-2 bg-zinc-800 rounded border border-zinc-750 text-xs">
                        <div className="flex items-center gap-2 overflow-hidden truncate">
                          {isImg ? (
                            <img src={url} alt="QC preview" className="w-8 h-8 rounded object-cover flex-shrink-0" />
                          ) : (
                            <FileText className="w-5 h-5 text-zinc-400 flex-shrink-0" />
                          )}
                          <span className="truncate text-zinc-300" title={filename}>{filename}</span>
                        </div>
                        <Button
                          type="button"
                          variant="ghost"
                          onClick={() => removeAttachment(url)}
                          className="h-6 w-6 p-0 hover:bg-zinc-700 text-zinc-400 hover:text-white rounded"
                        >
                          <X className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          <DialogFooter className="gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={loading}
              className="border-zinc-700 text-zinc-300 hover:bg-zinc-800 hover:text-white h-9 text-xs"
            >
              Hủy
            </Button>
            <Button
              type="submit"
              disabled={loading}
              className="bg-emerald-600 hover:bg-emerald-500 text-white h-9 text-xs"
            >
              {loading ? "Đang ghi nhận..." : "Gửi kết quả"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

import axios from "axios";

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5024/api";

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

// Request interceptor: tự động đính kèm accessToken
api.interceptors.request.use(
  (config) => {
    if (typeof window !== "undefined") {
      const token = localStorage.getItem("accessToken");
      if (token && config.headers) {
        config.headers.Authorization = `Bearer ${token}`;
      }
    }
    return config;
  },
  (error) => Promise.reject(error)
);

let isRefreshing = false;
let failedQueue: any[] = [];

const processQueue = (error: any, token: string | null = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

// Response interceptor: tự động refresh token khi gặp 401
api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    // Tránh infinite loop hoặc nếu không phải lỗi 401
    if (!error.response || error.response.status !== 401 || originalRequest._retry) {
      return Promise.reject(error);
    }

    // Nếu là request login/refresh-token bị lỗi 401 thì không refresh
    if (originalRequest.url?.includes("/auth/login") || originalRequest.url?.includes("/auth/refresh-token")) {
      return Promise.reject(error);
    }

    if (isRefreshing) {
      return new Promise((resolve, reject) => {
        failedQueue.push({ resolve, reject });
      })
        .then((token) => {
          originalRequest.headers.Authorization = `Bearer ${token}`;
          return api(originalRequest);
        })
        .catch((err) => Promise.reject(err));
    }

    originalRequest._retry = true;
    isRefreshing = true;

    if (typeof window !== "undefined") {
      const refreshToken = localStorage.getItem("refreshToken");
      if (!refreshToken) {
        isRefreshing = false;
        handleLogout();
        return Promise.reject(error);
      }

      try {
        const res = await axios.post(`${API_BASE_URL}/auth/refresh-token`, {
          refreshToken: refreshToken,
        });

        const { token: newAccessToken, refreshToken: newRefreshToken } = res.data;

        localStorage.setItem("accessToken", newAccessToken);
        localStorage.setItem("refreshToken", newRefreshToken);

        api.defaults.headers.common["Authorization"] = `Bearer ${newAccessToken}`;
        originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;

        processQueue(null, newAccessToken);
        isRefreshing = false;
        return api(originalRequest);
      } catch (refreshError: any) {
        processQueue(refreshError, null);
        isRefreshing = false;
        handleLogout();
        return Promise.reject(refreshError);
      }
    }

    return Promise.reject(error);
  }
);

function handleLogout() {
  if (typeof window !== "undefined") {
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    // Sử dụng window.location để chuyển hướng cưỡng bức về trang login
    if (window.location.pathname !== "/login") {
      window.location.href = "/login";
    }
  }
}

export default api;

